namespace sv_9da0572b2223407da4d8741a2ff48661.Models;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);

public record NotificationPrefs(
    bool EmailNotifications,
    bool PushNotifications,
    bool WeeklyDigest,
    List<string> MutedChannels);

public record SecuritySettings(
    bool TwoFactorEnabled,
    DateTime? LastPasswordChange,
    List<ActiveSession> Sessions);

public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);

public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@namespace sv_9da0572b2223407da4d8741a2ff48661.Components.Pages.Settings

<nav class="settings-sidebar">
    <ul>
        @foreach (var section in Sections)
        {
            <li class="@(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionChanged.InvokeAsync(section)">
                <span class="sidebar-icon">@GetIcon(section)</span>
                <span class="sidebar-label">@section</span>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@namespace sv_9da0572b2223407da4d8741a2ff48661.Components.Pages.Settings

<div class="settings-section">
    <h2>Profile</h2>

    <div class="avatar-preview">
        @if (!string.IsNullOrWhiteSpace(AvatarUrl))
        {
            <img src="@AvatarUrl" alt="Avatar" class="avatar-image" />
        }
        else
        {
            <div class="avatar-placeholder">No Avatar</div>
        }
        <p class="avatar-url-display">@AvatarUrl</p>
    </div>

    <div class="form-group">
        <label for="displayName">Display Name</label>
        <input id="displayName" type="text" @bind="DisplayName" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label for="email">Email</label>
        <input id="email" type="email" @bind="Email" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label for="bio">Bio</label>
        <textarea id="bio" rows="4" @bind="Bio" @bind:event="oninput"></textarea>
    </div>

    <div class="button-group">
        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@IsSaving">
            @(IsSaving ? "Saving..." : "Save Changes")
        </button>
        <button class="btn btn-secondary" @onclick="Discard">Discard Changes</button>
    </div>

    @if (ShowSuccess)
    {
        <div class="toast success">Profile saved successfully!</div>
    }
</div>

@code {
    [Parameter] public string DisplayName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Bio { get; set; } = "";
    [Parameter] public string AvatarUrl { get; set; } = "";
    [Parameter] public EventCallback<(string DisplayName, string Email, string Bio)> OnSave { get; set; }
    [Parameter] public EventCallback OnDiscard { get; set; }

    private bool IsSaving;
    private bool ShowSuccess;

    private async Task SaveAsync()
    {
        IsSaving = true;
        await OnSave.InvokeAsync((DisplayName, Email, Bio));
        IsSaving = false;
        ShowSuccess = true;
        _ = HideToastAsync();
    }

    private async Task HideToastAsync()
    {
        await Task.Delay(3000);
        ShowSuccess = false;
        StateHasChanged();
    }

    private async Task Discard()
    {
        await OnDiscard.InvokeAsync();
    }
}

@namespace sv_9da0572b2223407da4d8741a2ff48661.Components.Pages.Settings

<div class="settings-section">
    <h2>Notifications</h2>

    <div class="toggle-group">
        <label class="toggle-item">
            <input type="checkbox" @bind="EmailNotifications" />
            <span>Email Notifications</span>
        </label>

        <label class="toggle-item">
            <input type="checkbox" @bind="PushNotifications" />
            <span>Push Notifications</span>
        </label>

        <label class="toggle-item">
            <input type="checkbox" @bind="WeeklyDigest" />
            <span>Weekly Digest</span>
        </label>
    </div>

    <h3>Muted Channels</h3>
    <div class="channel-list">
        @foreach (var channel in AvailableChannels)
        {
            <label class="toggle-item">
                <input type="checkbox"
                       checked="@MutedChannels.Contains(channel)"
                       @onchange="(e) => ToggleChannel(channel, (bool)e.Value!)" />
                <span>@channel</span>
            </label>
        }
    </div>

    <div class="button-group">
        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@IsSaving">
            @(IsSaving ? "Saving..." : "Save Preferences")
        </button>
    </div>

    @if (ShowSuccess)
    {
        <div class="toast success">Preferences saved successfully!</div>
    }
</div>

@code {
    [Parameter] public bool EmailNotifications { get; set; }
    [Parameter] public bool PushNotifications { get; set; }
    [Parameter] public bool WeeklyDigest { get; set; }
    [Parameter] public List<string> MutedChannels { get; set; } = [];
    [Parameter] public List<string> AvailableChannels { get; set; } = [];
    [Parameter] public EventCallback<(bool Email, bool Push, bool Digest, List<string> Muted)> OnSave { get; set; }

    private bool IsSaving;
    private bool ShowSuccess;

    private void ToggleChannel(string channel, bool isMuted)
    {
        if (isMuted && !MutedChannels.Contains(channel))
        {
            MutedChannels = [..MutedChannels, channel];
        }
        else if (!isMuted)
        {
            MutedChannels = MutedChannels.Where(c => c != channel).ToList();
        }
    }

    private async Task SaveAsync()
    {
        IsSaving = true;
        await OnSave.InvokeAsync((EmailNotifications, PushNotifications, WeeklyDigest, MutedChannels));
        IsSaving = false;
        ShowSuccess = true;
        _ = HideToastAsync();
    }

    private async Task HideToastAsync()
    {
        await Task.Delay(3000);
        ShowSuccess = false;
        StateHasChanged();
    }
}

@namespace sv_9da0572b2223407da4d8741a2ff48661.Components.Pages.Settings
@using sv_9da0572b2223407da4d8741a2ff48661.Models

<div class="settings-section">
    <h2>Security</h2>

    <!-- Change Password Panel -->
    <div class="expandable-panel">
        <button class="panel-header" @onclick="() => PasswordPanelOpen = !PasswordPanelOpen">
            <span>Change Password</span>
            <span class="expand-icon">@(PasswordPanelOpen ? "▼" : "▶")</span>
        </button>

        @if (PasswordPanelOpen)
        {
            <div class="panel-body">
                <div class="form-group">
                    <label for="currentPassword">Current Password</label>
                    <input id="currentPassword" type="password" @bind="CurrentPassword" />
                </div>
                <div class="form-group">
                    <label for="newPassword">New Password</label>
                    <input id="newPassword" type="password" @bind="NewPassword" />
                </div>
                <div class="form-group">
                    <label for="confirmPassword">Confirm Password</label>
                    <input id="confirmPassword" type="password" @bind="ConfirmPassword" />
                </div>

                @if (!string.IsNullOrEmpty(PasswordError))
                {
                    <div class="error-message">@PasswordError</div>
                }
                @if (PasswordSuccess)
                {
                    <div class="toast success">Password updated successfully!</div>
                }

                <button class="btn btn-primary" @onclick="ChangePasswordAsync" disabled="@IsChangingPassword">
                    @(IsChangingPassword ? "Updating..." : "Update Password")
                </button>
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="tfa-section">
        <h3>Two-Factor Authentication</h3>
        <div class="tfa-status">
            <span class="status-indicator @(TwoFactorEnabled ? "enabled" : "disabled")">
                @(TwoFactorEnabled ? "✓ Enabled" : "✗ Disabled")
            </span>
            <label class="toggle-item">
                <input type="checkbox" @bind="TwoFactorEnabled" />
                <span>@(TwoFactorEnabled ? "Disable 2FA" : "Enable 2FA")</span>
            </label>
        </div>
        @if (LastPasswordChange.HasValue)
        {
            <p class="info-text">Last password change: @LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
        }
    </div>

    <!-- Active Sessions -->
    <div class="sessions-section">
        <h3>Active Sessions</h3>
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th>Action</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@session.LastActive.ToString("g")</td>
                        <td>
                            @if (session.Id != CurrentSessionId)
                            {
                                <button class="btn btn-danger btn-sm"
                                        @onclick="() => PromptRevoke(session)">
                                    Revoke
                                </button>
                            }
                            else
                            {
                                <span class="current-badge">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>

    <!-- Revoke Confirmation Dialog -->
    @if (SessionToRevoke is not null)
    {
        <div class="modal-overlay" @onclick="CancelRevoke">
            <div class="modal-dialog" @onclick:stopPropagation="true">
                <h4>Revoke Session</h4>
                <p>Are you sure you want to revoke the session on <strong>@SessionToRevoke.Device</strong> in <strong>@SessionToRevoke.Location</strong>?</p>
                <div class="button-group">
                    <button class="btn btn-danger" @onclick="ConfirmRevokeAsync">Revoke</button>
                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public bool TwoFactorEnabled { get; set; }
    [Parameter] public DateTime? LastPasswordChange { get; set; }
    [Parameter] public List<ActiveSession> Sessions { get; set; } = [];
    [Parameter] public string CurrentSessionId { get; set; } = "";
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }

    private bool PasswordPanelOpen;
    private string CurrentPassword = "";
    private string NewPassword = "";
    private string ConfirmPassword = "";
    private string? PasswordError;
    private bool PasswordSuccess;
    private bool IsChangingPassword;
    private ActiveSession? SessionToRevoke;

    private async Task ChangePasswordAsync()
    {
        PasswordError = null;
        PasswordSuccess = false;

        if (string.IsNullOrWhiteSpace(CurrentPassword) ||
            string.IsNullOrWhiteSpace(NewPassword))
        {
            PasswordError = "All fields are required.";
            return;
        }

        if (NewPassword != ConfirmPassword)
        {
            PasswordError = "New password and confirmation do not match.";
            return;
        }

        IsChangingPassword = true;
        try
        {
            await OnChangePassword.InvokeAsync((CurrentPassword, NewPassword));
            PasswordSuccess = true;
            CurrentPassword = "";
            NewPassword = "";
            ConfirmPassword = "";
        }
        catch (Exception ex)
        {
            PasswordError = ex.Message;
        }
        finally
        {
            IsChangingPassword = false;
        }
    }

    private void PromptRevoke(ActiveSession session)
    {
        SessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        SessionToRevoke = null;
    }

    private async Task ConfirmRevokeAsync()
    {
        if (SessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(SessionToRevoke.Id);
            SessionToRevoke = null;
        }
    }
}

@namespace sv_9da0572b2223407da4d8741a2ff48661.Components.Pages.Settings

<div class="settings-section">
    <h2>Appearance</h2>

    <!-- Theme Selector -->
    <div class="form-group">
        <label>Theme</label>
        <div class="radio-group">
            @foreach (var theme in new[] { "Light", "Dark", "System" })
