    {
        IsSaving = true;
        await OnSave.InvokeAsync((DisplayName, Email, Bio));
        IsSaving = false;
        ShowSuccess = true;
        _ = HideToastAsync();
    }

    private async Task HideToastAsync()
    {
        await Task.Delay(3000);
        ShowSuccess = false;
        StateHasChanged();
    }

    private async Task Discard()
    {
        await OnDiscard.InvokeAsync();
    }
}

