@namespace sv_9da0572b2223407da4d8741a2ff48661.Components.Pages.Settings
@using sv_9da0572b2223407da4d8741a2ff48661.Models

<div class="settings-section">
    <h2>Security</h2>

    <!-- Change Password Panel -->
    <div class="expandable-panel">
        <button class="panel-header" @onclick="() => PasswordPanelOpen = !PasswordPanelOpen">
            <span>Change Password</span>
            <span class="expand-icon">@(PasswordPanelOpen ? "▼" : "▶")</span>
        </button>

        @if (PasswordPanelOpen)
        {
            <div class="panel-body">
                <div class="form-group">
                    <label for="currentPassword">Current Password</label>
                    <input id="currentPassword" type="password" @bind="CurrentPassword" />
                </div>
                <div class="form-group">
                    <label for="newPassword">New Password</label>
                    <input id="newPassword" type="password" @bind="NewPassword" />
                </div>
                <div class="form-group">
                    <label for="confirmPassword">Confirm Password</label>
                    <input id="confirmPassword" type="password" @bind="ConfirmPassword" />
                </div>

                @if (!string.IsNullOrEmpty(PasswordError))
                {
                    <div class="error-message">@PasswordError</div>
                }
                @if (PasswordSuccess)
                {
                    <div class="toast success">Password updated successfully!</div>
                }

                <button class="btn btn-primary" @onclick="ChangePasswordAsync" disabled="@IsChangingPassword">
                    @(IsChangingPassword ? "Updating..." : "Update Password")
                </button>
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="tfa-section">
        <h3>Two-Factor Authentication</h3>
        <div class="tfa-status">
            <span class="status-indicator @(TwoFactorEnabled ? "enabled" : "disabled")">
                @(TwoFactorEnabled ? "✓ Enabled" : "✗ Disabled")
            </span>
            <label class="toggle-item">
                <input type="checkbox" @bind="TwoFactorEnabled" />
                <span>@(TwoFactorEnabled ? "Disable 2FA" : "Enable 2FA")</span>
            </label>
        </div>
        @if (LastPasswordChange.HasValue)
        {
            <p class="info-text">Last password change: @LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
        }
    </div>

    <!-- Active Sessions -->
    <div class="sessions-section">
        <h3>Active Sessions</h3>
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th>Action</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@session.LastActive.ToString("g")</td>
                        <td>
                            @if (session.Id != CurrentSessionId)
                            {
                                <button class="btn btn-danger btn-sm"
                                        @onclick="() => PromptRevoke(session)">
                                    Revoke
                                </button>
                            }
                            else
                            {
                                <span class="current-badge">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>

    <!-- Revoke Confirmation Dialog -->
    @if (SessionToRevoke is not null)
    {
        <div class="modal-overlay" @onclick="CancelRevoke">
            <div class="modal-dialog" @onclick:stopPropagation="true">
                <h4>Revoke Session</h4>
                <p>Are you sure you want to revoke the session on <strong>@SessionToRevoke.Device</strong> in <strong>@SessionToRevoke.Location</strong>?</p>
                <div class="button-group">
                    <button class="btn btn-danger" @onclick="ConfirmRevokeAsync">Revoke</button>
                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public bool TwoFactorEnabled { get; set; }
    [Parameter] public DateTime? LastPasswordChange { get; set; }
    [Parameter] public List<ActiveSession> Sessions { get; set; } = [];
    [Parameter] public string CurrentSessionId { get; set; } = "";
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }

    private bool PasswordPanelOpen;
    private string CurrentPassword = "";
    private string NewPassword = "";
    private string ConfirmPassword = "";
    private string? PasswordError;
    private bool PasswordSuccess;
    private bool IsChangingPassword;
    private ActiveSession? SessionToRevoke;

    private async Task ChangePasswordAsync()
    {
        PasswordError = null;
        PasswordSuccess = false;

        if (string.IsNullOrWhiteSpace(CurrentPassword) ||
            string.IsNullOrWhiteSpace(NewPassword))
        {
            PasswordError = "All fields are required.";
            return;
        }

        if (NewPassword != ConfirmPassword)
        {
            PasswordError = "New password and confirmation do not match.";
            return;
        }

        IsChangingPassword = true;
        try
        {
            await OnChangePassword.InvokeAsync((CurrentPassword, NewPassword));
            PasswordSuccess = true;
            CurrentPassword = "";
            NewPassword = "";
            ConfirmPassword = "";
        }
        catch (Exception ex)
        {
            PasswordError = ex.Message;
        }
        finally
        {
            IsChangingPassword = false;
        }
    }

    private void PromptRevoke(ActiveSession session)
    {
        SessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        SessionToRevoke = null;
    }

    private async Task ConfirmRevokeAsync()
    {
        if (SessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(SessionToRevoke.Id);
            SessionToRevoke = null;
        }
    }
}

