@namespace sv_9da0572b2223407da4d8741a2ff48661.Components.Pages.Settings

<div class="settings-section">
    <h2>Appearance</h2>

    <!-- Theme Selector -->
    <div class="form-group">
        <label>Theme</label>
        <div class="radio-group">
            @foreach (var theme in new[] { "Light", "Dark", "System" })
            {
                <label class="radio-item">
                    <input type="radio" name="theme" value="@theme"
                           checked="@(Theme == theme)"
                           @onchange="() => Theme = theme" />
                    <span>@theme</span>
                </label>
            }
        </div>
    </div>

    <!-- Font Size Selector -->
    <div class="form-group">
        <label>Font Size</label>
        <div class="radio-group">
            @foreach (var size in new[] { "Small", "Medium", "Large" })
            {
                <label class="radio-item">
                    <input type="radio" name="fontSize" value="@size"
                           checked="@(FontSize == size)"
                           @onchange="() => FontSize = size" />
                    <span>@size</span>
                </label>
            }
        </div>
    </div>

    <!-- Language Dropdown -->
    <div class="form-group">
        <label for="language">Language</label>
        <select id="language" @bind="Language">
            <option value="en">English</option>
            <option value="es">Español</option>
            <option value="fr">Français</option>
            <option value="de">Deutsch</option>
            <option value="ja">日本語</option>
            <option value="zh">中文</option>
        </select>
    </div>

    <!-- Compact Mode Toggle -->
    <label class="toggle-item">
        <input type="checkbox" @bind="CompactMode" />
        <span>Compact Mode</span>
    </label>

    <!-- Live Preview -->
    <div class="preview-area @GetPreviewClasses()">
        <h4>Live Preview</h4>
        <p class="preview-text">This is how your content will look with the selected settings.</p>
        <div class="preview-card">
            <strong>Sample Card</strong>
            <p>Content appears in your chosen theme and font size.</p>
        </div>
    </div>

    <div class="button-group">
        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@IsSaving">
            @(IsSaving ? "Saving..." : "Save")
        </button>
    </div>

    @if (ShowSuccess)
    {
        <div class="toast success">Appearance settings saved!</div>
    }
</div>

@code {
    [Parameter] public string Theme { get; set; } = "System";
    [Parameter] public string FontSize { get; set; } = "Medium";
    [Parameter] public string Language { get; set; } = "en";
    [Parameter] public bool CompactMode { get; set; }
    [Parameter] public EventCallback<(string Theme, string FontSize, string Language, bool CompactMode)> OnSave { get; set; }

    private bool IsSaving;
    private bool ShowSuccess;

    private string GetPreviewClasses()
    {
        var theme = Theme.ToLowerInvariant();
        var size = FontSize.ToLowerInvariant();
        var compact = CompactMode ? "compact" : "";
        return $"theme-{theme} font-{size} {compact}".Trim();
    }

    private async Task SaveAsync()
    {
        IsSaving = true;
        await OnSave.InvokeAsync((Theme, FontSize, Language, CompactMode));
        IsSaving = false;
        ShowSuccess = true;
        _ = HideToastAsync();
    }

    private async Task HideToastAsync()
    {
        await Task.Delay(3000);
        ShowSuccess = false;
        StateHasChanged();
    }
}

