.sessions-table th {
    background: var(--card-bg, #f8f9fa);
    font-weight: 600;
    font-size: 0.85rem;
    color: var(--text-secondary, #6c757d);
}

.sessions-table td {
    font-size: 0.9rem;
}

.current-badge {
    font-size: 0.8rem;
    padding: 0.2rem 0.5rem;
    background: #cfe2ff;
    color: #084298;
    border-radius: 0.25rem;
}

/* Modal / Confirmation Dialog */
.modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal-dialog {
    background: white;
    padding: 1.5rem;
    border-radius: 0.5rem;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.2);
}

.modal-dialog h4 {
    margin: 0 0 0.75rem;
}

.modal-dialog p {
    margin: 0 0 1.25rem;
    color: var(--text-secondary, #6c757d);
}

/* Toast Messages */
.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 0.375rem;
    font-size: 0.9rem;
    animation: fadeIn 0.3s ease-in;
}

.toast.success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

.error-message {
    color: #dc3545;
    font-size: 0.85rem;
    margin-bottom: 0.75rem;
}

/* Live Preview Area */
.preview-area {
    margin-top: 1.5rem;
    padding: 1.5rem;
    border: 2px dashed var(--border-color, #dee2e6);
    border-radius: 0.5rem;
    transition: all 0.3s ease;
}

.preview-area h4 {
    margin: 0 0 0.5rem;
}

.preview-card {
    margin-top: 0.75rem;
    padding: 1rem;
    border-radius: 0.375rem;
    border: 1px solid var(--border-color, #dee2e6);
}

/* Theme variants */
.preview-area.theme-light {
    background: #ffffff;
    color: #212529;
}

.preview-area.theme-dark {
    background: #1e1e2e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-area.theme-dark .preview-card {
    background: #2d2d3f;
    border-color: #555;
}

.preview-area.theme-system {
    background: #f8f9fa;
    color: #212529;
}

/* Font size variants */
.preview-area.font-small {
    font-size: 0.8rem;
}

.preview-area.font-medium {
    font-size: 1rem;
}

.preview-area.font-large {
    font-size: 1.2rem;
}

/* Compact mode */
.preview-area.compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.preview-area.compact .preview-card {
    padding: 0.5rem;
    margin-top: 0.5rem;
}

/* Loading State */
.loading {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 200px;
    color: var(--text-secondary, #6c757d);
    font-size: 1.1rem;
}

/* Animation */
@keyframes fadeIn {
    from { opacity: 0; transform: translateY(-0.5rem); }
    to { opacity: 1; transform: translateY(0); }
}
