@page "/settings"
@using sv_9da0572b2223407da4d8741a2ff48661.Models
@using sv_9da0572b2223407da4d8741a2ff48661.Components.Pages.Settings
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@activeSection"
                    OnSectionChanged="@((s) => activeSection = s)" />

    <main class="settings-content">
        @if (isLoading)
        {
            <div class="loading">Loading settings...</div>
        }
        else
        {
            @switch (activeSection)
            {
                case "Profile":
                    <ProfileSection DisplayName="@profileDisplayName"
                                    Email="@profileEmail"
                                    Bio="@profileBio"
                                    AvatarUrl="@profileAvatarUrl"
                                    OnSave="@SaveProfileAsync"
                                    OnDiscard="@DiscardProfile" />
                    break;

                case "Notifications":
                    <NotificationsSection EmailNotifications="@notifEmail"
                                          PushNotifications="@notifPush"
                                          WeeklyDigest="@notifDigest"
                                          MutedChannels="@mutedChannels"
                                          AvailableChannels="@availableChannels"
                                          OnSave="@SaveNotificationsAsync" />
                    break;

                case "Security":
                    <SecuritySection TwoFactorEnabled="@twoFactorEnabled"
                                     LastPasswordChange="@lastPasswordChange"
                                     Sessions="@sessions"
                                     CurrentSessionId="@currentSessionId"
                                     OnChangePassword="@ChangePasswordAsync"
                                     OnRevokeSession="@RevokeSessionAsync" />
                    break;

                case "Appearance":
                    <AppearanceSection Theme="@appTheme"
                                       FontSize="@appFontSize"
                                       Language="@appLanguage"
                                       CompactMode="@appCompactMode"
                                       OnSave="@SaveAppearanceAsync" />
                    break;
            }
        }
    </main>
</div>

@code {
    private string activeSection = "Profile";
    private bool isLoading = true;

    // Profile state
    private string profileDisplayName = "";
    private string profileEmail = "";
    private string profileBio = "";
    private string profileAvatarUrl = "";
    private UserProfile? savedProfile;

    // Notifications state
    private bool notifEmail;
    private bool notifPush;
    private bool notifDigest;
    private List<string> mutedChannels = [];
    private List<string> availableChannels = ["general", "announcements", "random", "engineering", "design", "marketing"];

    // Security state
    private bool twoFactorEnabled;
    private DateTime? lastPasswordChange;
    private List<ActiveSession> sessions = [];
    private string currentSessionId = "";

    // Appearance state
    private string appTheme = "System";
    private string appFontSize = "Medium";
    private string appLanguage = "en";
    private bool appCompactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettingsAsync();
        isLoading = false;
    }

    private async Task LoadAllSettingsAsync()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        // Profile
        savedProfile = profileTask.Result;
        ApplyProfile(savedProfile);

        // Notifications
        var notif = notifTask.Result;
        notifEmail = notif.EmailNotifications;
        notifPush = notif.PushNotifications;
        notifDigest = notif.WeeklyDigest;
        mutedChannels = notif.MutedChannels.ToList();

        // Security
        var security = securityTask.Result;
        twoFactorEnabled = security.TwoFactorEnabled;
        lastPasswordChange = security.LastPasswordChange;
        sessions = security.Sessions.ToList();
        if (sessions.Count > 0)
        {
            currentSessionId = sessions[0].Id;
        }

        // Appearance
        var appearance = appearanceTask.Result;
        appTheme = appearance.Theme;
        appFontSize = appearance.FontSize;
        appLanguage = appearance.Language;
        appCompactMode = appearance.CompactMode;
    }

    private void ApplyProfile(UserProfile profile)
    {
        profileDisplayName = profile.DisplayName;
        profileEmail = profile.Email;
        profileBio = profile.Bio;
        profileAvatarUrl = profile.AvatarUrl;
    }

    private async Task SaveProfileAsync((string DisplayName, string Email, string Bio) data)
    {
        var updated = new UserProfile(data.DisplayName, data.Email, profileAvatarUrl, data.Bio);
        await SettingsService.SaveProfileAsync(updated);
        savedProfile = updated;
        ApplyProfile(savedProfile);
    }

    private Task DiscardProfile()
    {
        if (savedProfile is not null)
        {
            ApplyProfile(savedProfile);
        }
        return Task.CompletedTask;
    }

    private async Task SaveNotificationsAsync((bool Email, bool Push, bool Digest, List<string> Muted) data)
    {
        var prefs = new NotificationPrefs(data.Email, data.Push, data.Digest, data.Muted);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        notifEmail = data.Email;
        notifPush = data.Push;
        notifDigest = data.Digest;
        mutedChannels = data.Muted;
    }

    private async Task ChangePasswordAsync((string Current, string New) data)
    {
        await SettingsService.ChangePasswordAsync(data.Current, data.New);
        lastPasswordChange = DateTime.UtcNow;
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        sessions = sessions.Where(s => s.Id != sessionId).ToList();
    }

    private async Task SaveAppearanceAsync((string Theme, string FontSize, string Language, bool CompactMode) data)
    {
        var settings = new AppearanceSettings(data.Theme, data.FontSize, data.Language, data.CompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        appTheme = data.Theme;
        appFontSize = data.FontSize;
        appLanguage = data.Language;
        appCompactMode = data.CompactMode;
    }
}

