+        appTheme = appearance.Theme;
+        appFontSize = appearance.FontSize;
+        appLanguage = appearance.Language;
+        appCompactMode = appearance.CompactMode;
+    }
+
+    private void ApplyProfile(UserProfile profile)
+    {
+        profileDisplayName = profile.DisplayName;
+        profileEmail = profile.Email;
+        profileBio = profile.Bio;
+        profileAvatarUrl = profile.AvatarUrl;
+    }
+
+    private async Task SaveProfileAsync((string DisplayName, string Email, string Bio) data)
+    {
+        var updated = new UserProfile(data.DisplayName, data.Email, profileAvatarUrl, data.Bio);
+        await SettingsService.SaveProfileAsync(updated);
+        savedProfile = updated;
+        ApplyProfile(savedProfile);
+    }
+
+    private Task DiscardProfile()
+    {
+        if (savedProfile is not null)
+        {
+            ApplyProfile(savedProfile);
+        }
+        return Task.CompletedTask;
+    }
+
+    private async Task SaveNotificationsAsync((bool Email, bool Push, bool Digest, List<string> Muted) data)
+    {
+        var prefs = new NotificationPrefs(data.Email, data.Push, data.Digest, data.Muted);
+        await SettingsService.SaveNotificationPrefsAsync(prefs);
+        notifEmail = data.Email;
+        notifPush = data.Push;
+        notifDigest = data.Digest;
+        mutedChannels = data.Muted;
+    }
+
+    private async Task ChangePasswordAsync((string Current, string New) data)
+    {
+        await SettingsService.ChangePasswordAsync(data.Current, data.New);
+        lastPasswordChange = DateTime.UtcNow;
+    }
+
+    private async Task RevokeSessionAsync(string sessionId)
+    {
+        await SettingsService.RevokeSessionAsync(sessionId);
+        sessions = sessions.Where(s => s.Id != sessionId).ToList();
+    }
+
+    private async Task SaveAppearanceAsync((string Theme, string FontSize, string Language, bool CompactMode) data)
+    {
+        var settings = new AppearanceSettings(data.Theme, data.FontSize, data.Language, data.CompactMode);
